from collections import Counter
def f(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v==1:
                for di,dj in ((-1,0),(1,0),(0,-1),(0,1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg: g[ni][nj]=7
            elif v==2:
                for di,dj in ((-1,-1),(-1,1),(1,-1),(1,1)):
                    ni,nj=i+di,j+dj
                    if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg: g[ni][nj]=4
    return g
